import{_ as o,C as r,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Stages","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/setup/stages.md","filePath":"master/human-resources/recruitment/setup/stages.md","lastUpdated":1793074831000}'),l={name:"master/human-resources/recruitment/setup/stages.md"};function g(h,e,d,c,p,m){const a=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to &quot;Stages&quot;">​</a></h1><p>Stages are the steps of your hiring process. Every applicant sits in one stage at a time. You move the applicant forward as the hiring goes on. Each stage also carries labels for the applicant state, and a flag that marks the stage as hired.</p><blockquote><p><strong>In simple words:</strong> A stage is one step in your hiring process, such as First Interview or Contract Signed.</p></blockquote><p>Open <code>Recruitments → Configuration → Stages</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Job positions are optional on a stage. If you want to link them, create them first. See <a href="./../job-positions/job-positions.html">Job positions</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows the columns <strong>Stage Name</strong>, <strong>Job Positions</strong>, <strong>Default Stage</strong>, <strong>Folded</strong> and <strong>Hired Stage</strong>. Each flag shows as an icon. A green tick means yes. A red cross means no. <strong>New</strong> is the default stage. <strong>Contract Signed</strong> is the hired stage. The stage bar on an applicant shows the order from left to right: <strong>New</strong>, <strong>First Interview</strong>, <strong>Initial Qualification</strong>, <strong>Second Interview</strong>, <strong>Document Verification</strong>, <strong>Contract Proposal</strong>, <strong>Contract Signed</strong>.</p><p>Drag a row to change the order. Use the filter to find a stage by name or job position. Group the list by name or label.</p>',8)),s(a,{src:"/images1/recruitment/set_stages_list.png",alt:"Stages list with the Job Positions badges and the Default Stage, Folded and Hired Stage columns showing green ticks and red crosses"}),e[1]||(e[1]=t('<h2 id="create-a-stage" tabindex="-1">Create a stage <a class="header-anchor" href="#create-a-stage" aria-label="Permalink to &quot;Create a stage&quot;">​</a></h2><p>This example adds a stage named <strong>Background Check</strong>.</p><ol><li>Open <code>Recruitments → Configuration → Stages</code>.</li><li>Click <strong>New Stage</strong>. A full page titled <strong>Create Stages</strong> opens.</li><li>Fill in the fields below.</li><li>Click <strong>Create</strong>.</li></ol>',3)),s(a,{src:"/images1/recruitment/set_stage_create_form.png",alt:"Create Stages form filled for Background Check with the three tooltip labels, Warehouse Supervisor as job position and the Folded, Hired Stage and Default Stage toggles off"}),e[2]||(e[2]=t('<h3 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to &quot;General Information&quot;">​</a></h3><ul><li><strong><em>Stage Name:</em></strong> (required) the name shown on the stage bar.</li><li><strong><em>Requirements:</em></strong> a short note about what must happen in this stage.</li></ul><h3 id="tooltips" tabindex="-1">Tooltips <a class="header-anchor" href="#tooltips" aria-label="Permalink to &quot;Tooltips&quot;">​</a></h3><p>These three labels name the states an applicant can have in this stage. They show as the tooltip text on the <strong>State</strong> button.</p><ul><li><strong><em>Gray Label:</em></strong> (required) starts as <strong>In Progress</strong>.</li><li><strong><em>Red Label:</em></strong> (required) starts as <strong>Blocked</strong>.</li><li><strong><em>Green Label:</em></strong> (required) starts as <strong>Ready for Next Stage</strong>.</li></ul><p>You can rename them per stage. For example, use <strong>Waiting for documents</strong> in a verification stage.</p><h3 id="additional-information" tabindex="-1">Additional Information <a class="header-anchor" href="#additional-information" aria-label="Permalink to &quot;Additional Information&quot;">​</a></h3><ul><li><strong><em>Job Positions:</em></strong> link the stage to the positions that use it.</li><li><strong><em>Folded:</em></strong> a toggle. It starts off.</li><li><strong><em>Hired Stage:</em></strong> a toggle. When on, an applicant who enters this stage is marked <strong>Hired</strong>.</li><li><strong><em>Default Stage:</em></strong> a toggle. When on, new applicants start in this stage.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>In the sample data, <strong>New</strong> is the default stage and <strong>Contract Signed</strong> is the hired stage. If you turn <strong>Hired Stage</strong> off on <strong>Contract Signed</strong>, applicants who reach it are no longer marked hired.</p></div><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><p>Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. Use the select boxes to delete many rows at once. Move the applicants out of a stage before you delete it.</p><p>The view page is titled <strong>View Stages</strong>. It has <strong>Edit</strong> and <strong>Delete</strong> buttons at the top right. It also shows <strong>Sequence Order</strong>, the position of the stage in the pipeline.</p>',12)),s(a,{src:"/images1/recruitment/set_stage_view.png",alt:"View Stages page for First Interview with Sequence Order 1 and the Gray, Red and Green labels"}),e[3]||(e[3]=t('<h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>When you click a stage on the stage bar of an applicant, Aureus saves the move at once. If the stage has <strong>Hired Stage</strong> on, the applicant is marked <strong>Hired</strong>. Leaving it reopens the application. The state returns to the first label, <strong>In Progress</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../applicants/process-applicant.html">Process an applicant</a></li><li><a href="./refuse-reasons.html">Refuse reasons</a></li><li><a href="./">Setup overview</a></li></ul>',4))])}const _=o(l,[["render",g]]);export{f as __pageData,_ as default};
